mapper.select:
SELECT '0' AS id, '' AS adminId, '-1' AS pId, #{headerName} AS name, null AS msgCnt, 'U' AS folderType, 0 AS folderOrder, 'true' AS open, CONCAT(#{contextPath}, '/resources/img/ztree/mouse_right.png') AS icon UNION ALL SELECT A.FOLDER_SEQ AS id, A.ADMIN_ID AS adminId, A.P_FOLDER_SEQ AS pId, A.FOLDER_NM AS name, B.CNT AS msgCnt, A.FOLDER_TYPE AS folderType, A.FOLDER_ORDER AS folderOrder, A.FOLDER_OPEN AS open, CASE WHEN FOLDER_TYPE='D' AND B.CNT > 0 THEN CONCAT(#{contextPath}, '/resources/img/ztree/msgFolder.png') WHEN FOLDER_TYPE='D' THEN CONCAT(#{contextPath}, '/resources/img/ztree/msgFolder_empty.png') WHEN FOLDER_TYPE='F' THEN '' END AS icon FROM UI_FOLDER_ADMIN A LEFT JOIN (SELECT FOLDER_SEQ, COUNT(MSGID) AS CNT FROM UI_FOLDER_MESSAGE GROUP BY FOLDER_SEQ) B ON A.FOLDER_SEQ = B.FOLDER_SEQ WHERE ADMIN_ID = #{adminId}
AND FOLDER_NM LIKE CONCAT('%', #{searchStr}, '%')
ORDER BY pId ASC, folderOrder ASC

SELECT FOLDER_SEQ AS id, P_FOLDER_SEQ AS pId, FOLDER_NM AS name, FOLDER_TYPE AS folderType, FOLDER_ORDER AS folderOrder, 'false' AS open FROM UI_FOLDER_ADMIN A WHERE A.ADMIN_ID = #{adminId}
AND FIND_IN_SET(FOLDER_SEQ, REPLACE(#{folder_ids}, '|', ','))
ORDER BY pId ASC, folderOrder ASC

mapper.update:
UPDATE UI_FOLDER_ADMIN SET 
FOLDER_NM = #{name} 
WHERE FOLDER_SEQ = #{id} AND ADMIN_ID = #{adminId}

UPDATE UI_FOLDER_ADMIN SET FOLDER_OPEN = #{open}

	, P_FOLDER_SEQ = #{pId}

WHERE FOLDER_SEQ = #{id} AND ADMIN_ID = #{adminId}

UPDATE	UI_FOLDER_ADMIN
SET		FOLDER_ORDER = #{folderOrder},
		P_FOLDER_SEQ = #{pId}
		WHERE	FOLDER_SEQ = #{id}
AND		ADMIN_ID = #{adminId}

