SELECT  COUNT(*) AS CNT
FROM	UI_FOLDER_MESSAGE
WHERE	FOLDER_SEQ = #{folderSeq}

SELECT  FOLDER_SEQ AS folderSeq, MSGID AS msgId, CONSENT_NO AS consentNo
FROM	UI_FOLDER_MESSAGE
WHERE	FOLDER_SEQ = #{folderSeq}
ORDER BY MSGID DESC
LIMIT	${limit}
OFFSET	${offset}

